from shared import source_css,canonical_css,samples
import pathlib,json
P=pathlib.Path(__file__).parent;t=json.loads((P/'tokens.json').read_text());s=t['samples']
css=source_css()+'''*{box-sizing:border-box}body{margin:0;font-family:var(--font-sans);color:var(--ink)}section{width:1000px;height:760px;background:var(--canvas);padding:48px 56px}h1{font-size:44px;line-height:1.3;margin:12px 0 30px;letter-spacing:-1px}h2{font-size:28px;margin:0}p{margin:0}.k{font-size:20px;color:var(--secondary)}.r{display:flex;justify-content:space-between;gap:24px;border-top:1px solid var(--line);padding:23px 0;font-size:32px;line-height:1.35}.r b{font-weight:600}.r span{color:var(--secondary)}.note{background:var(--surface);padding:22px 26px;margin-top:24px;font-size:23px;line-height:1.5}.cta{display:inline-block;background:var(--citron);padding:14px 24px;font-size:26px;font-weight:600;margin-top:24px;border-radius:6px}.foot{font-size:17px;color:var(--secondary);margin-top:22px}.status{font-size:32px}.r.status span{max-width:48%}'''
css=canonical_css(css)
a='<section id="deck-activity-focus"><div class="k">Wringy / 活动要求</div><h1>'+s['activity']+'</h1><div class="r"><span>拍摄对象</span><b>'+s['product']+'</b></div><div class="r"><span>内容要求</span><b>主体清晰 · 使用过程完整</b></div><div class="r"><span>提交材料</span><b>预览作品 ＋ 内容说明</b></div><div class="note">先提交预览作品，确认发布前审核结果。<br>发布后再进入最终审核。</div><div class="cta">查看参与要求 →</div><p class="foot">示例活动 · 产品流程提案，业务规则待批准</p></section>'
b='<section id="deck-review-focus"><div class="k">Wringy / 作品 001</div><h1>水瓶日常使用演示</h1><div class="r status"><span>发布前审核</span><b>通过</b></div><div class="r status"><span>最终审核</span><b>尚未开始</b></div><div class="r status"><span>奖励资格</span><b>尚未确认</b></div><div class="r status"><span>银行实际付款</span><b>尚未付款</b></div><div class="note">审核记录：画面包含主体与使用细节。<br>下一步：提交发布链接，等待最终审核。</div><p class="foot">示例记录 · 审核通过不等于已付款</p></section>'
(P/'deck-focus.html').write_text(samples('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><style>'+css+'</style>'+a+b+'</html>'))
